wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use std::collections::BTreeSet;

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // Ids already emitted in this batch, so a duplicate entry is dropped too.
        let mut emitted: BTreeSet<String> = BTreeSet::new();
        let mut out = Vec::with_capacity(items.len());

        for item in items {
            if emitted.contains(&item.id) {
                continue;
            }
            // `id` is a parser-computed digest, so it is safe to use as a store key.
            if state_read::get(&item.id).is_some() {
                continue;
            }
            emitted.insert(item.id.clone());
            out.push(item);
        }

        out
    }
}

export!(Node);
